+use std::process;
+
+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
+enum StoiError {
+    InvalidArgument,
+    OutOfRange,
+}
+
+pub fn parse_complexity_or_abort<I>(args: I) -> i32
+where
+    I: IntoIterator<Item = String>,
+{
+    let mut args = args.into_iter();
+    let _program = args.next();
+
+    match args.next() {
+        Some(raw) => match parse_i32_prefix(&raw) {
+            Ok(value) => value.min(5),
+            Err(err) => abort_like_cpp(err),
+        },
+        None => 3,
+    }
+}
+
+fn parse_i32_prefix(input: &str) -> Result<i32, StoiError> {
+    let bytes = input.as_bytes();
+    let mut index = 0usize;
+
+    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
+        index += 1;
+    }
+
+    let mut negative = false;
+    if index < bytes.len() {
+        match bytes[index] {
+            b'+' => index += 1,
+            b'-' => {
+                negative = true;
+                index += 1;
+            }
+            _ => {}
+        }
+    }
+
+    let digit_start = index;
+    let mut magnitude: u64 = 0;
+    let limit = if negative {
+        (i32::MAX as u64) + 1
+    } else {
+        i32::MAX as u64
+    };
+
+    while index < bytes.len() {
+        let byte = bytes[index];
+        if !byte.is_ascii_digit() {
+            break;
+        }
+
+        magnitude = magnitude
+            .checked_mul(10)
+            .and_then(|value| value.checked_add((byte - b'0') as u64))
+            .ok_or(StoiError::OutOfRange)?;
+
+        if magnitude > limit {
+            return Err(StoiError::OutOfRange);
+        }
+
+        index += 1;
+    }
+
+    if index == digit_start {
+        return Err(StoiError::InvalidArgument);
+    }
+
+    if negative {
+        if magnitude == limit {
+            Ok(i32::MIN)
+        } else {
+            Ok(-(magnitude as i32))
+        }
+    } else {
+        Ok(magnitude as i32)
+    }
+}
+
+fn abort_like_cpp(error: StoiError) -> ! {
+    match error {
+        StoiError::InvalidArgument => {
+            eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
+        }
+        StoiError::OutOfRange => {
+            eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
+        }
+    }
+    eprintln!("  what():  stoi");
+    process::abort();
+}
