+        let args = vec!["test20".to_string()];
+        assert_eq!(parse_complexity_or_abort(args), 3);
+    }
+
+    #[test]
+    fn clamps_at_five() {
+        let args = vec!["test20".to_string(), "6".to_string()];
+        assert_eq!(parse_complexity_or_abort(args), 5);
+    }
+
+    #[test]
+    fn keeps_negative_values() {
+        let args = vec!["test20".to_string(), "-1".to_string()];
+        assert_eq!(parse_complexity_or_abort(args), -1);
+    }
+
+    #[test]
+    fn accepts_stoi_style_prefixes() {
+        let args = vec!["test20".to_string(), "2abc".to_string()];
+        assert_eq!(parse_complexity_or_abort(args), 2);
+    }
